import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

public class Partial_withField_TriageGen1Test {

    @Test
    public void testWithField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        int value = 2023;
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{value});

        // If the value is the same, it should return 'this' (same instance)
        Partial result = partial.withField(yearType, value);

        assertSame("Should return the same instance when value is unchanged", partial, result);
    }

    @Test
    public void testWithField_DifferentValue_ReturnsNewInstance() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        int[] types = {yearType.getSortOrder().ordinal(), monthType.getSortOrder().ordinal()}; // Simplified for mock-like behavior

        // Using actual types for a real Partial object
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2023, 1});

        // Change year
        Partial result = partial.withField(yearType, 2024);

        assertNotSame("Should return a new instance when value is changed", partial, result);
        assertEquals("New year should be 2024", 2024, result.getValue(0));
        assertEquals("Month should remain 1", 1, result.getValue(1));
    }

    @Test
    public void testWithField_MultipleFields_UpdatesCorrectField() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonth();

        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType, dayType}, new int[]{2023, 5, 15});

        // Update only the month
        Partial result = partial.withField(monthType, 12);

        assertEquals("Year should remain 2023", 2023, result.getValue(0));
        assertEquals("Month should be updated to 12", 12, result.getValue(1));
        assertEquals("Day should remain 15", 15, result.getValue(2));
    }

    @Test
    public void testWithField_VerifyArrayIntegrity() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020});

        Partial result = partial.withField(yearType, 2021);

        int[] originalValues = partial.getValues();
        int[] newValues = result.getValues();

        assertEquals("Original array should not be modified", 2020, originalValues[0]);
        assertEquals("New array should contain updated value", 2021, newValues[0]);
        assertNotSame("The underlying value arrays should be different objects", originalValues, newValues);
    }
}
